 public sealed partial class Simulation {
  public readonly List<PlayerSkillProjectile> PlayerSkillProjectiles=new List<PlayerSkillProjectile>();int nextPlayerSkillProjectileId=1;float skillAimX,skillAimY;public float MaliceHuntCd,VenomBladeCd,LtnChaserCd,PlagueBurstCd;
  double SkillFuseMultiplier(string id){int star=0;foreach(var key in Skills.Fused){var f=FullSkillLedger.Fusion(key);if(f!=null&&Array.IndexOf(f.Members,id)>=0)star=Math.Max(star,f.Star);}double result=star>=2?1+(star-1)*.2:1;return id=="chargeBoost"||id=="magicBlink"?result:result*(1+(EquippedInventory?.AffixTotal("skillBoost")??0));}
  public double SkillDexMultiplier(){var inv=EquippedInventory;var gl=inv?.GetEquipped("gloves");double dex=Crossbow.DexFlat+(int)(Player.Level*.5),unique=0,legend=0;if(inv!=null)foreach(var i in inv.Equipped){if(i==null)continue;if(unique==0&&i.uniqueSpecial=="_uGloveSpd")unique=i.uniqueVal;if(i.legendarySpecial=="_lGloveElem")legend+=i.legendaryVal;}return 1+dex*.0005+(gl?.atkSpd??0)+(inv?.AffixTotal("atkSpeed")??0)+(inv?.ImplicitTotal("_iAtkSpd")??0)*.01+unique+(legend>0?.2:0);}
  double SkillMeleeMultiplier(){return .7*(1+PassiveAtk*.10+Config.PassiveHuman*.05+PassiveMelee*.15+Crossbow.AltAtk);}
  double SkillBladePierceBonus(bool lightning=false,bool flat=true){double bow=EquippedInventory?.GetEquipped("bow")?.bowPierce??0;return Js.Int(bow*(lightning?30:300)+Growth.Value("pPierce")*(lightning?3:30))+(flat?(EquippedInventory?.AffixTotal("pierceFlat")??0):0);}
  PlayerSkillProjectile NewSkillProjectile(double a){var p=new PlayerSkillProjectile{Id=nextPlayerSkillProjectileId++,X=Player.X+Math.Cos(a)*16,Y=Player.Y+Math.Sin(a)*16,Vx=Math.Cos(a)*18,Vy=Math.Sin(a)*18};PlayerSkillProjectiles.Add(p);return p;}
  bool CastBladeSkill(string id){int lv=Math.Max(1,Skills.Level(id));float cd=id=="maliceHunt"?MaliceHuntCd:id=="venomBlade"?VenomBladeCd:id=="ltnChaser"?LtnChaserCd:PlagueBurstCd;int stamina=id=="maliceHunt"?50:id=="plagueBurst"?0:40,malice=id=="maliceHunt"?30:id=="plagueBurst"?15:0;
   if(cd>0||Player.Stamina<stamina||Materials<MaliceCost(malice)){DenySkill(id,cd>0?"cooldown":Player.Stamina<stamina?"stamina":"malice");return false;}
   // Guardian/echo fusions are admitted only after their executors join this runtime.
   if(id=="maliceHunt"&&Skills.Fused.Contains("bladeEcho")){DenySkill(id,"fusion-not-ready");return false;}
   bool guardian=id=="maliceHunt"&&Skills.Learned("guardian")&&Skills.Fused.Contains("bladeFuse");if(guardian&&!GuardianReleaseReady()){DenySkill(id,"guardian-or-plague-not-ready");return false;}
   int paid;if(!TrySpendMalice(malice,out paid))return false;Player.Stamina=Math.Max(0,Player.Stamina-stamina);double a=id=="venomBlade"||id=="ltnChaser"?Math.Atan2(skillAimY-Player.Y,skillAimX-Player.X):attackAngle;
   if(id=="venomBlade"||id=="ltnChaser"){attackAngle=(float)a;Player.Facing=(float)a;}
   if(id=="maliceHunt"&&guardian){ReleaseGuardianBlades(lv);MaliceHuntCd=Math.Max(600,Js.Int(900*(1+CooldownReduction)));}
   else if(id=="maliceHunt"){var p=NewSkillProjectile(a);p.Damage=Js.Int(MeleeReference()*SkillMeleeMultiplier()*SkillRules.SkMul("maliceHuntBurst",Math.Max(1,Skills.Level("maliceHuntBurst"))));p.MaxDist=2000+(lv-1)*100;p.Radius=10;p.Stagger=8;p.MaliceHunt=p.MhBlade=true;p.MaxPierce=800+(lv-1)*20+SkillBladePierceBonus();p.MaxBounce=10;MaliceHuntCd=Math.Max(600,Js.Int(900*(1+CooldownReduction)));}
   else if(id=="venomBlade"){int count=Math.Min(6,1+lv),pool=Js.Int(BowRef()*SkillDexMultiplier()*PassDmgSum("bow")*SkillRules.SkMul(id,lv)*SkillFuseMultiplier(id));for(int i=0;i<count;i++){var p=NewSkillProjectile(a+(i-(count-1)/2.0)*.12);p.Damage=1;p.Element=3;p.MaxDist=6000+(lv-1)*300;p.Radius=8;p.MhBlade=p.VenomBlade=true;p.VenomPool=pool;p.MaxPierce=800+(lv-1)*20+SkillBladePierceBonus();p.MaxBounce=10;}VenomBladeCd=Math.Max(600,Js.Int(900*(1+CooldownReduction)));}
   else if(id=="ltnChaser"){int count=Math.Min(12,2+lv*2),damage=Js.Int(BowRef()*SkillDexMultiplier()*PassDmgSum("bow")*SkillRules.SkMul(id,lv)*SkillFuseMultiplier(id));for(int i=0;i<count;i++){var p=NewSkillProjectile(a+(i-(count-1)/2.0)*.15);p.Damage=damage;p.Element=4;p.MaxDist=99999;p.Radius=8;p.Stagger=4;p.Knockback=1;p.MhBlade=p.LtnChaser=p.Lightning=true;p.ChainMax=Math.Min(8,3+lv/2);p.ChainRange=250+lv*10;p.MaxPierce=500+(lv-1)*20+SkillBladePierceBonus(true);p.MaxBounce=20;}LtnChaserCd=Math.Max(480,Js.Int(720*(1+CooldownReduction)));}
   else{var p=NewSkillProjectile(a);p.MaxDist=2000+(lv-1)*100;p.Radius=10;p.PlagueBlade=p.PlagueHoming=true;p.PlagueLevel=lv;p.MaxPierce=800+(lv-1)*20+SkillBladePierceBonus(false,false)+100;p.PlagueCap=(int)Math.Floor(p.MaxPierce*91/1000)+9;p.MaxBounce=p.PlagueCap;PlagueBurstCd=Math.Max(600,Js.Int(900*(1+CooldownReduction)));}
