  }
  void TickBladeSkillPreparation(float x,float y){skillAimX=x;skillAimY=y;if(MaliceHuntCd>0)MaliceHuntCd--;if(VenomBladeCd>0)VenomBladeCd--;if(LtnChaserCd>0)LtnChaserCd--;if(PlagueBurstCd>0)PlagueBurstCd--;}
 }
 public sealed class SkillChainArc {public double X1,Y1,X2,Y2;public int T,MaxT=18;}
