  EnemyState ProjectileTarget(PlayerSkillProjectile p,double range,bool homing){EnemyState best=null,fallback=null;double bd=range,fd=range;bool checkedAlive=false;var near=ShQuery(p.X,p.Y,range,true);foreach(var e in near){if(!e.Alive)continue;if(p.HitSet.Contains(e)&&!p.VenomBlade){if((p.PlagueHoming||p.MhBlade)&&!checkedAlive){checkedAlive=true;bool any=false;foreach(var other in near)if(other.Alive&&!p.HitSet.Contains(other)){any=true;break;}if(!any)p.HitSet.Clear();}continue;}double d=ZoneDistance(p.X,p.Y,e.X,e.Y);if(p.VenomBlade&&p.HitSet.Contains(e)){if(d<fd){fd=d;fallback=e;}continue;}if(d<bd){bd=d;best=e;}}return best??fallback;}
