  void TickPlayerSkillProjectiles(){for(int i=SkillChainArcs.Count-1;i>=0;i--)if(++SkillChainArcs[i].T>=SkillChainArcs[i].MaxT)SkillChainArcs.RemoveAt(i);int write=0;for(int i=0;i<PlayerSkillProjectiles.Count;i++){var p=PlayerSkillProjectiles[i];if(!p.Active)continue;p.TrailX[p.TrailHead]=p.X;p.TrailY[p.TrailHead]=p.Y;p.TrailHead=(p.TrailHead+1)%12;p.TrailLength=Math.Min(12,p.TrailLength+1);double speed=Math.Sqrt(p.Vx*p.Vx+p.Vy*p.Vy);if(p.BounceCool>0)p.BounceCool--;if(p.VenomBlade&&p.Rehit>0)p.Rehit=Math.Max(0,p.Rehit-1);
   if(p.BounceCool<=0&&speed>0&&(TickCount+i)%2==0){double range=p.PlagueHoming||p.MhBlade?(p.Pierced==0?1000:500):p.ChainMax>0?400:p.Magic?250:200;var target=ProjectileTarget(p,range,true);if(target!=null){double a=Math.Atan2(target.Y-p.Y,target.X-p.X),current=Math.Atan2(p.Vy,p.Vx),delta=a-current;while(delta>Math.PI)delta-=Math.PI*2;while(delta<-Math.PI)delta+=Math.PI*2;double turn=p.VenomBlade?3:p.PlagueHoming||p.MhBlade?1.5:p.ChainMax>0?.7:p.Magic?.35:.25;a=current+Math.Min(Math.Abs(delta),turn)*Math.Sign(delta);p.Vx=Math.Cos(a)*speed;p.Vy=Math.Sin(a)*speed;}}
   p.X+=p.Vx;p.Y+=p.Vy;p.Dist+=speed;if(p.Grace>0)p.Grace--;bool dead=p.LtnChaser&&ZoneDistance(p.X,p.Y,Player.X,Player.Y)>1000;
   if(!dead&&p.Dist>p.MaxDist)dead=true;else if(!dead&&BoltWall(p.X,p.Y)){int max=p.MaxBounce!=0?p.MaxBounce:3;if((p.Magic||p.MhBlade)&&p.Bounces<max){p.X-=p.Vx;p.Y-=p.Vy;for(int esc=0;esc<5&&BoltWall(p.X,p.Y);esc++){p.X-=p.Vx;p.Y-=p.Vy;}bool h=BoltWall(p.X+p.Vx,p.Y),v=BoltWall(p.X,p.Y+p.Vy);if(h)p.Vx=-p.Vx;if(v)p.Vy=-p.Vy;if(!h&&!v){p.Vx=-p.Vx;p.Vy=-p.Vy;}p.Bounces++;p.BounceCool=6;if(p.PlagueHoming||p.MhBlade){EnemyState best=null;double bd=1000;foreach(var e in Enemies){if(!e.Alive||p.HitSet.Contains(e))continue;double d=ZoneDistance(p.X,p.Y,e.X,e.Y);if(d<bd){bd=d;best=e;}}if(best!=null){double a=Math.Atan2(best.Y-p.Y,best.X-p.X);if(!BoltWall(p.X+Math.Cos(a)*20,p.Y+Math.Sin(a)*20))AimProjectile(p,best,speed);}}}else dead=true;}
   if(dead){p.Active=false;continue;}bool hit=HurtFieldMobs(p.X,p.Y,p.Radius+8,p.Damage!=0?p.Damage:10,p.HitFieldSet);foreach(var e in ShQuery(p.X,p.Y,p.Radius+20,true)){if(!e.Alive||p.HitSet.Contains(e)&&!p.PlagueBlade&&!p.VenomBlade||ZoneDistance(p.X,p.Y,e.X,e.Y)>=e.Radius+p.Radius)continue;
    if(p.LtnChaser&&p.MaxPierce>0){if(p.Grace>0||p.HitSet.Contains(e)){hit=false;continue;}p.HitSet.Add(e);ProjectileDamage(p,e,p.Damage);if(p.ChainMax>p.ChainCount){var set=new HashSet<EnemyState>(p.HitSet);set.Add(e);var previous=e;int dmg=p.Damage;for(int n=0;n<p.ChainMax-p.ChainCount;n++){EnemyState next=null;double bd=p.ChainRange!=0?p.ChainRange:180;foreach(var ce in ShQuery(previous.X,previous.Y,bd,true)){if(!ce.Alive||set.Contains(ce))continue;double d=ZoneDistance(previous.X,previous.Y,ce.X,ce.Y);if(d<bd){bd=d;next=ce;}}if(next==null)break;set.Add(next);dmg=Js.Int(dmg*.8);ProjectileDamage(p,next,dmg,previous.X,previous.Y,new EnemyHurtOpts{lightning=true,ltnChaser=true},4,true);if(SkillChainArcs.Count<60)SkillChainArcs.Add(new SkillChainArc{X1=previous.X,Y1=previous.Y,X2=next.X,Y2=next.Y});previous=next;}}
     int count=0;foreach(var active in PlayerSkillProjectiles)if(active.Active&&active.LtnChaser)count++;int half=Js.Int(p.MaxPierce/2);if(half>=1&&count<100){double a=Math.Atan2(p.Vy,p.Vx);for(int k=0;k<2;k++){double sa=a+(k==0?-.3:.3);var child=new PlayerSkillProjectile{Id=nextPlayerSkillProjectileId++,X=p.X,Y=p.Y,Vx=Math.Cos(sa)*18,Vy=Math.Sin(sa)*18,Damage=p.Damage,Element=p.Element,MaxDist=3000,Radius=p.Radius,Stagger=p.Stagger,Knockback=p.Knockback,Magic=true,LtnChaser=true,MhBlade=true,Lightning=true,ChainMax=p.ChainMax,ChainRange=p.ChainRange,ChainCount=p.ChainCount,MaxPierce=half,MaxBounce=p.MaxBounce,Grace=15};child.HitSet.UnionWith(p.HitSet);PlayerSkillProjectiles.Add(child);}hit=true;break;}p.Pierced++;int guaranteed=(int)Math.Floor(p.MaxPierce*91/100);if(p.Pierced<=guaranteed){hit=false;continue;}double chance=Math.Max(0,1-(p.Pierced-guaranteed));if(chance>0&&SkillRandom()<chance){hit=false;continue;}}
    if(p.VenomBlade){if(p.Rehit>0){hit=false;continue;}p.Rehit=8;bool repeated=p.HitSet.Contains(e);p.HitSet.Add(e);p.Pierced+=repeated?2:1;ProjectileDamage(p,e,Js.Int(p.VenomPool*.15));var w=e.Web??SyncToWeb(e);w.poison=1;w.poisonT=Math.Max(w.poisonT,600);double prior=w.poisonStk;if(prior<50){w.poisonStk=prior+1;w._poisonPool+=(1+Growth.Value("pDot")*.05)*p.VenomPool*(1+prior*.5)*1.5;}if(BladePierceSurvives(p)){hit=false;continue;}hit=true;break;}
    if(p.PlagueBlade){if(p.HitSet.Contains(e)){if(p.Rehit>0)continue;p.Rehit=8;}if(p.Rehit>0)p.Rehit--;var w=SyncToWeb(e);if(w._plagued!=true)w._plagueStack=0;if((w._plagueStack??0)<30){w._plagued=true;w._plagueLv=p.PlagueLevel!=0?p.PlagueLevel:1;w._plagueStack=(w._plagueStack??0)+1;}p.PlagueHit++;p.PlagueTargets.Add(new[]{(double)e.X,e.Y});p.HitSet.Add(e);int cap=p.PlagueCap!=0?p.PlagueCap:p.MaxPierce!=0?(int)p.MaxPierce:30;if(p.PlagueHit>=cap){int lv=p.PlagueLevel!=0?p.PlagueLevel:1;ProjectileDamage(p,e,Js.Int((500+(lv-1)*100)*.6),options:new EnemyHurtOpts(),element:3);int radius=Js.Int((160+(lv-1)*10)*.5),damage=Js.Int(MagicReference()*MagicDamageMultiplier()*SkillRules.SkMul("plagueBurst",Math.Max(1,Skills.Level("plagueBurst"))));var victims=new HashSet<EnemyState>{e};foreach(var point in p.PlagueTargets)foreach(var other in Enemies.ToArray()){if(!other.Alive||victims.Contains(other)||ZoneDistance(point[0],point[1],other.X,other.Y)>=radius)continue;victims.Add(other);ProjectileDamage(p,other,damage,point[0],point[1],new EnemyHurtOpts(),3);var ow=other.Web??SyncToWeb(other);if(ow._plagued!=true){ow._plagued=true;ow._plagueLv=lv;}}HurtShake(15);hit=true;break;}hit=false;continue;}
    var ew=SyncToWeb(e);double mult=EnemyHurt.ElMul(p.Element,ew.el);int damageDone=Js.Int(p.Damage*mult);ProjectileDamage(p,e,damageDone);ew=e.Web??SyncToWeb(e);if(p.MaliceHunt){ew.bleed=1;ew.bleedT=Math.Max(ew.bleedT,900);ew.bleedStk++;if(ew.bleedStk<10)ew._bleedPool+=(1+Growth.Value("pDot")*.05)*Math.Max(1,Js.Int(damageDone*.1));}
    if(p.Magic&&!p.MaliceHunt&&p.Knockback>0){double a=Math.Atan2(e.Y-p.Y,e.X-p.X);e.KnockbackX+=(float)(Math.Cos(a)*p.Knockback*mult);e.KnockbackY+=(float)(Math.Sin(a)*p.Knockback*mult);}
    if(p.MaliceHunt&&p.MaxPierce>0){p.HitSet.Add(e);p.Pierced++;ew._mhDot=(ew._mhDot??0)+150;ew._mhDotDmg=Js.Int(p.Damage*.15);if(BladePierceSurvives(p)){hit=false;continue;}}
    if(p.ChainMax>p.ChainCount){p.HitSet.Add(e);EnemyState next=null;double bd=p.ChainRange!=0?p.ChainRange:180;foreach(var ce in ShQuery(e.X,e.Y,bd,true)){if(!ce.Alive||ce==e||p.HitSet.Contains(ce))continue;double d=ZoneDistance(e.X,e.Y,ce.X,ce.Y);if(d<bd){bd=d;next=ce;}}if(next!=null){double a=Math.Atan2(next.Y-e.Y,next.X-e.X);var child=new PlayerSkillProjectile{Id=nextPlayerSkillProjectileId++,X=e.X,Y=e.Y,Vx=Math.Cos(a)*8,Vy=Math.Sin(a)*8,Damage=Js.Int(p.Damage*.7),Element=4,MaxDist=bd+80,Radius=4,Stagger=2,Knockback=1,Magic=true,Lightning=true,ChainMax=p.ChainMax,ChainRange=p.ChainRange,ChainCount=p.ChainCount+1};child.HitSet.UnionWith(p.HitSet);PlayerSkillProjectiles.Add(child);}hit=true;break;}if(p.PierceProbability>0&&SkillRandom()<p.PierceProbability&&p.PierceCount<(p.PierceMax>0?p.PierceMax:1)){p.PierceCount++;p.Damage=Js.Int(p.Damage*Math.Min(1,.85+Growth.Value("pPierce")*.03));p.HitSet.Add(e);hit=false;continue;}hit=true;break;
   }if(!hit)PlayerSkillProjectiles[write++]=p;else p.Active=false;
  }if(PlayerSkillProjectiles.Count>write)PlayerSkillProjectiles.RemoveRange(write,PlayerSkillProjectiles.Count-write);}
  bool BladePierceSurvives(PlayerSkillProjectile p){int guaranteed=(int)Math.Floor(p.MaxPierce*91/1000);if(p.Pierced<=guaranteed)return true;double chance=Math.Max(0,1-(p.Pierced-guaranteed)*.1);return chance>0&&SkillRandom()<chance;}
